mapper.select:
SELECT st.student_id AS studentId, st.student_name AS studentName, st.grade_key AS gradeKey, gc.grade_name AS gradeName, st.clinic_grade_key AS clinicGradeKey, cd.codeNm AS clinicGradeName, st.billing_phone AS billingPhone, CONVERT(VARCHAR(10), st.created_at, 23) AS registeredAt, (SELECT CONVERT(VARCHAR(10), MAX(cs.session_date), 23) FROM erp_bookstore_clinic_session cs WHERE cs.student_id = st.student_id) AS lastVisitDate, (SELECT COUNT(*) FROM erp_bookstore_recommend_log rl WHERE rl.student_id = st.student_id AND rl.status = 'DONE') AS totalDoneBooks, st.status_key AS statusKey FROM erp_student st LEFT JOIN erp_grade_code gc ON gc.grade_key = st.grade_key LEFT JOIN erp_bookstore_code cd ON cd.gubun = 'S' AND cd.code = st.clinic_grade_key WHERE st.center_code = #{centerCode} AND st.grade_key = #{gradeKey} AND st.status_key = #{statusKey}
AND (st.student_name LIKE '%' + #{keyword} + '%' OR st.billing_phone LIKE '%' + #{keyword} + '%')
ORDER BY st.student_name ASC

SELECT COUNT(*)
FROM erp_student s
JOIN erp_student_guardian g ON s.student_id = g.student_id
WHERE s.student_name = #{studentName}
  AND g.tel_middle   = #{telMiddle}
  AND g.tel_last     = #{telLast}
